-- (1) update warning.warning_hazard_type_general with 'RIG_LIST' where a part has warning_hazard_type_detail='DRILLING_RIG_SHIP_ON_LOCATION'
UPDATE warning SET warning_hazard_type_general = 'RIG_LIST' WHERE id IN (
    SELECT w.id FROM warning w
    INNER JOIN warning_feature_part wfp ON wfp.warning_id = w.id
    INNER JOIN warning_feature_part_warning_hazard_type_details wfpwhtd ON wfp.id = wfpwhtd.feature_part_id
    WHERE wfpwhtd.warning_hazard_type_detail = 'DRILLING_RIG_SHIP_ON_LOCATION'
);
-- (2) remove from warning_feature_part_warning_hazard_type_details where warning_hazard_type_detail='DRILLING_RIG_SHIP_ON_LOCATION'
DELETE FROM warning_feature_part_warning_hazard_type_details WHERE warning_hazard_type_detail='DRILLING_RIG_SHIP_ON_LOCATION';

CREATE OR REPLACE FUNCTION update_subscription_sub_area( old_sub_area_name TEXT, new_sub_area_name TEXT ) RETURNS VOID AS $$
BEGIN
DELETE FROM subscription_sub_area ssa WHERE sub_area_id = ( SELECT sa.id FROM sub_area sa INNER JOIN serie_sub_area ssa ON ssa.sub_area_id = sa.id INNER JOIN serie s ON s.id = ssa.serie_id WHERE sa.name = old_sub_area_name AND s.name = 'AVINAV BREST') AND EXISTS ( SELECT subscription_id FROM subscription_sub_area ssa2 WHERE ssa2.subscription_id = ssa.subscription_id AND ssa2.sub_area_id = ( SELECT sa.id FROM sub_area sa INNER JOIN serie_sub_area ssa ON ssa.sub_area_id = sa.id INNER JOIN serie s ON s.id = ssa.serie_id WHERE sa.name = new_sub_area_name AND s.name = 'AVINAV BREST'));
UPDATE subscription_sub_area SET sub_area_id = ( SELECT sa.id FROM sub_area sa INNER JOIN serie_sub_area ssa ON ssa.sub_area_id = sa.id INNER JOIN serie s ON s.id = ssa.serie_id WHERE sa.name = new_sub_area_name AND s.name = 'AVINAV BREST') WHERE sub_area_id = ( SELECT sa.id FROM sub_area sa INNER JOIN serie_sub_area ssa ON ssa.sub_area_id = sa.id INNER JOIN serie s ON s.id = ssa.serie_id WHERE sa.name = old_sub_area_name AND s.name = 'AVINAV BREST');
END $$ LANGUAGE plpgsql;

SELECT update_subscription_sub_area('ILLE-ET-VILAINE', 'CASQUETS');
SELECT update_subscription_sub_area('COTES D ARMOR', 'CASQUETS');
SELECT update_subscription_sub_area('FINISTERE', 'IROISE');
SELECT update_subscription_sub_area('MORBIHAN', 'IROISE');
SELECT update_subscription_sub_area('LOIRE-ATLANTIQUE', 'YEU');
SELECT update_subscription_sub_area('VENDEE', 'YEU');
SELECT update_subscription_sub_area('CHARENTE MARITIME', 'ROCHEBONNE');
SELECT update_subscription_sub_area('GIRONDE', 'ROCHEBONNE');
SELECT update_subscription_sub_area('LANDES', 'CANTABRICO');
SELECT update_subscription_sub_area('PYRENEES-ATLANTIQUE', 'CANTABRICO');

WITH duplicates AS (
    SELECT
        id,
        ROW_NUMBER() OVER (PARTITION BY warning_id, sub_area_id ORDER BY id) AS row_num
    FROM warning_general_area
)
DELETE FROM warning_general_area
WHERE id IN (
    SELECT id FROM duplicates WHERE row_num > 1
);

